/**
 * The Great Pyramid in the hand (chapter 6, docs/exhibit-2026-10.md, "Objects in the hand"): the solid generated by
 * @seked/geometry from the bundle's base and original height, with chapter 6's numbers drawn on it: the circle whose
 * radius is the height laid on the ground round it (A1), the triangle of half the base, the height and the apothem
 * cut through it on its south face (A2), and a line to true north. No Blender and no file: everything is computed
 * from the database when the leaf is reached. Kept free of three.js so it can be tested and imported eagerly.
 */
import { pyramidMesh, type Mesh } from '@seked/geometry';

/** A point in the project frame (+X east, +Y north, +Z up) as three.js holds it (+Y up, north toward -Z). */
export const toThree = ([x, y, z]: number[]): [number, number, number] => [x!, z!, -y!];

export interface PyramidObject {
  mesh: Mesh;
  side: number;
  height: number;
  /** The ground circle of radius the height, the A2 triangle and the north line, each a polyline in the project frame. */
  circle: number[][];
  triangle: number[][];
  north: number[][];
}

/** The pyramid and its lines from the claims' environment; null without the monuments. */
export function pyramidObject(ground: Record<string, number>, segments = 128): PyramidObject | null {
  const side = ground['g1.base.side.mean'], height = ground['g1.height.original'];
  if (side === undefined || height === undefined) return null;
  const circle = Array.from({ length: segments + 1 }, (_, i) => {
    const a = (i / segments) * 2 * Math.PI;
    return [height * Math.cos(a), height * Math.sin(a), 0];
  });
  return {
    mesh: pyramidMesh({ base: side, height }),
    side, height, circle,
    // the centre, the middle of the south side, the apex, and back down the axis
    triangle: [[0, 0, 0], [0, -side / 2, 0], [0, 0, height], [0, 0, 0]],
    north: [[0, 0, 0], [0, height * 1.25, 0]],
  };
}
